from decimal import Decimal
from typing import Dict, List
import pandas as pd

class GLBuilderAgent:
    """Agent 1: Reconstructs general ledger from raw transactions"""

    def __init__(self, chart_of_accounts: Dict[str, str]):
        self.coa = chart_of_accounts
        self.journal_entries = []
        self.gl = pd.DataFrame(columns=['Date', 'Account', 'Debit', 'Credit', 'Description'])

    def deduplicate_transactions(self, transactions: pd.DataFrame) -> pd.DataFrame:
        """Remove duplicate transactions from multiple sources"""
        # Sort by date and amount
        transactions = transactions.sort_values(['Date', 'Amount'])

        duplicates = []
        for i in range(len(transactions) - 1):
            current = transactions.iloc[i]
            next_txn = transactions.iloc[i + 1]

            # Same amount within 2 days = likely duplicate
            if (abs(current['Amount'] - next_txn['Amount']) < 0.01 and
                abs((current['Date'] - next_txn['Date']).days) <= 2):
                duplicates.append(i + 1)

        return transactions.drop(transactions.index[duplicates])

    def create_journal_entry(self, date, debit_account, credit_account, amount, description):
        """Create double-entry journal entry"""
        je = {
            'date': date,
            'entries': [
                {'account': debit_account, 'debit': amount, 'credit': Decimal('0'), 'description': description},
                {'account': credit_account, 'debit': Decimal('0'), 'credit': amount, 'description': description}
            ]
        }
        self.journal_entries.append(je)
        return je

    def post_to_gl(self, journal_entry):
        """Post journal entry to general ledger"""
        for entry in journal_entry['entries']:
            self.gl = pd.concat([self.gl, pd.DataFrame([{
                'Date': journal_entry['date'],
                'Account': entry['account'],
                'Debit': entry['debit'],
                'Credit': entry['credit'],
                'Description': entry['description']
            }])], ignore_index=True)

    def validate_balance(self) -> bool:
        """Validate: Total Debits = Total Credits"""
        total_debits = self.gl['Debit'].sum()
        total_credits = self.gl['Credit'].sum()
        return abs(total_debits - total_credits) < Decimal('0.01')

class ExpenseCategorizerAgent:
    """Agent 2: Categorize expenses using ML + keyword rules"""

    KEYWORD_RULES = {
        '5000': ['GOOGLE ADS', 'FACEBOOK ADS', 'ADVERTISING', 'MARKETING'],
        '5100': ['EXXON', 'SHELL', 'CHEVRON', 'BP', 'MOBIL', 'GAS STATION'],
        '5300': ['UPWORK', 'FIVERR', 'CONTRACTOR', 'FREELANCE'],
        '5500': ['STATE FARM', 'GEICO', 'INSURANCE'],
        '5700': ['LAW OFFICE', 'ATTORNEY', 'CPA', 'ACCOUNTANT'],
        '5800': ['STAPLES', 'OFFICE DEPOT', 'AMAZON', 'OFFICE'],
        '5900': ['RENT', 'LEASE', 'LANDLORD'],
        '6000': ['REPAIR', 'MAINTENANCE', 'FIX'],
        '6100': ['SUPPLIES', 'MATERIALS'],
        '6300': ['HOTEL', 'AIRLINE', 'UBER', 'RESTAURANT'],
        '6400': ['ELECTRIC', 'VERIZON', 'AT&T', 'INTERNET', 'UTILITY'],
    }

    def categorize(self, description: str, amount: Decimal) -> str:
        """Categorize transaction based on description and amount"""
        upper_desc = description.upper()

        # Keyword matching
        for account, keywords in self.KEYWORD_RULES.items():
            for keyword in keywords:
                if keyword in upper_desc:
                    return account

        # Amount-based rules
        if 'INSURANCE' in upper_desc and amount > 500:
            return '5500'  # Insurance (recurring premium)

        if any(word in upper_desc for word in ['RESTAURANT', 'CAFE', 'DINER']):
            return '6300'  # Meals (50% deductible)

        # Default to Other Expenses
        return '6900'

    def get_confidence(self, description: str, category: str) -> float:
        """Return confidence score (0-1) for categorization"""
        upper_desc = description.upper()

        if category in self.KEYWORD_RULES:
            keywords = self.KEYWORD_RULES[category]
            if any(keyword in upper_desc for keyword in keywords):
                return 0.95

        return 0.60  # Low confidence, needs manual review
